(()=>{let saved;try{saved=localStorage.getItem('uniify-appearance')}catch{}document.documentElement.dataset.appearance=saved||(document.body?.classList.contains('management')||/workspace/.test(location.pathname)?'dark':null)||(/workspace|onboarding|signin|signup|verify|forgot/.test(location.pathname)?'light':'dark');document.documentElement.dataset.theme=document.documentElement.dataset.appearance;function sync(){document.querySelectorAll('[data-theme-toggle]').forEach(b=>{const dark=document.documentElement.dataset.appearance==='dark';b.innerHTML=dark?'<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/></svg>':'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 15A8 8 0 0 1 9 4a8 8 0 1 0 11 11Z"/></svg>';b.title=dark?'Switch to light theme':'Switch to dark theme';b.setAttribute('aria-label',dark?'Switch to light theme':'Switch to dark theme');b.setAttribute('aria-pressed',String(dark))})}document.addEventListener('DOMContentLoaded',sync);document.addEventListener('click',e=>{if(!e.target.closest('[data-theme-toggle]'))return;const next=document.documentElement.dataset.appearance==='dark'?'light':'dark';document.documentElement.dataset.appearance=next;document.documentElement.dataset.theme=next;try{localStorage.setItem('uniify-appearance',next)}catch{}sync()})})();
